// Clean-room TSVC s115 profile; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s115_upper_triangular_saxpy_elimination(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<8||length>58{return -1;}let v=core::slice::from_raw_parts(input,length);if v[0]<2||v[0]>7||v[1]<1||v[1]>3{return -1;}let n=v[0]as usize;let passes=v[1]as usize;if length!=2+n+n*n{return -1;}let mut a=[0i64;8];let mut m=[0i64;64];for i in 0..n{let x=v[2+i];if !(-1..=1).contains(&x){return -1;}a[i]=x;}for i in 0..n*n{let x=v[2+n+i];if !(-1..=1).contains(&x){return -1;}m[i]=x;}if output.is_null()||capacity<8*n{return -2;}for _ in 0..passes{for j in 0..n{for i in j+1..n{a[i]-=m[j*n+i]*a[j];}}}for i in 0..n{let b=a[i]as u64;for k in 0..8{output.add(8*i+k).write((b>>(8*k))as u8);}}n as i64}
